def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError(f"The file {commands_file_path} does not exist.")

    if not os.path.exists(output_dir_path):
        os.makedirs(output_dir_path)

    output_file_paths = []

    with open(commands_file_path, mode='r', encoding='utf-8') as csv_file:
        csv_reader = csv.reader(csv_file)
        for index, row in enumerate(csv_reader):
            if not row:
                continue

            command = row[0]
            output_file_name = f'command_{index}_output.txt'
            output_file_path = os.path.join(output_dir_path, output_file_name)

            try:
                result = subprocess.run(command, shell=True, capture_output=True, text=True)

                with open(output_file_path, 'w', encoding='utf-8') as out_file:
                    if result.returncode == 0:
                        out_file.write(result.stdout)
                    else:
                        out_file.write(f"Command failed with exit code {result.returncode}\n")
                        out_file.write(f"Error Message: {result.stderr}")
            except Exception as e:
                with open(output_file_path, 'w', encoding='utf-8') as out_file:
                    out_file.write(f"An unexpected error occurred: {str(e)}")

            output_file_paths.append(output_file_path)

    return output_file_paths

