import threading
def task_func(file_list):
    exit_codes = [None] * len(file_list)
    threads = []

    def run_file(index, file_path):
        try:
            result = subprocess.run([file_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            exit_codes[index] = result.returncode
        except Exception:
            exit_codes[index] = -1

    for i, file_path in enumerate(file_list):
        t = threading.Thread(target=run_file, args=(i, file_path))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return exit_codes

